t":["/** Step ids in wizard order. Mirrors `SetupSteps::ids()` (see contract.json). */\r\nexport const STEP_IDS = [\r\n\t'welcome',\r\n\t'experience',\r\n\t'preferences',\r\n\t'niche',\r\n\t'pages',\r\n\t'import',\r\n] as const;\r\nexport type StepId = ( typeof STEP_IDS )[ number ];\r\n\r\nexport const EXPERIENCES = [\r\n\t'beginner',\r\n\t'intermediate',\r\n\t'experienced',\r\n] as const;\r\nexport type Experience = ( typeof EXPERIENCES )[ number ];\r\n\r\nexport const NICHES = [\r\n\t'digital-marketing-growth',\r\n\t'tech-skills',\r\n\t'creator-economy',\r\n\t'academic-test-prep',\r\n\t'other',\r\n] as const;\r\nexport type Niche = ( typeof NICHES )[ number ];\r\n\r\nexport const CURRENCY_POSITIONS = [\r\n\t'left',\r\n\t'right',\r\n\t'left_space',\r\n\t'right_space',\r\n] as const;\r\nexport type CurrencyPosition = ( typeof CURRENCY_POSITIONS )[ number ];\r\n\r\nexport const STATUSES = [\r\n\t'not_started',\r\n\t'in_progress',\r\n\t'completed',\r\n\t'dismissed',\r\n] as const;\r\nexport type WizardStatus = ( typeof STATUSES )[ number ];\r\n\r\nexport type StepStatus = 'pending' | 'done' | 'skipped';\r\n\r\nexport interface StepInfo {\r\n\tid: StepId;\r\n\tstatus: StepStatus;\r\n\tskippable: boolean;\r\n\tavailable: boolean;\r\n}\r\n\r\nexport type PageStatus = 'ready' | 'adoptable' | 'missing';\r\n\r\nexport interface StarterPage {\r\n\tkey: string;\r\n\ttitle: string;\r\n\tslug: string;\r\n\tpage_id: number;\r\n\tstatus: PageStatus;\r\n}\r\n\r\nexport interface Preferences {\r\n\tcurrency: string;\r\n\tcurrency_pos: string;\r\n\tprice_num_decimals: number;\r\n}\r\n\r\nexport interface SetupState {\r\n\tversion: number;\r\n\tstatus: WizardStatus;\r\n\tcurrentStep: StepId | null;\r\n\tsteps: StepInfo[];\r\n\tanswers: {\r\n\t\texperience: Experience | null;\r\n\t\tniche: Niche | null;\r\n\t\ttopics: string[];\r\n\t};\r\n\tpreferences: Preferences;\r\n\tstarterPages: StarterPage[];\r\n\tstartedAt: string | null;\r\n\tcompletedAt: string | null;\r\n}\r\n\r\nexport interface PageAction {\r\n\tkey: string;\r\n\tpage_id: number;\r\n\taction: 'kept' | 'adopted' | 'created';\r\n}\r\n\r\nexport interface StepResult {\r\n\tchanged: string[];\r\n\tpages: PageAction[];\r\n}\r\n\r\nexport interface StepResponse {\r\n\tstate: SetupState;\r\n\tresult: StepResult;\r\n}\r\n\r\n/** Body of a step request. */\r\nexport interface ExperienceInput {\r\n\texperience: Experience;\r\n}\r\nexport interface PreferencesInput {\r\n\tcurrency: string;\r\n\tcurrency_pos: CurrencyPosition;\r\n\tprice_num_decimals: number;\r\n}\r\nexport interface NicheInput {\r\n\tniche: Niche;\r\n\ttopics: string[];\r\n}\r\nexport type StepInput =\r\n\tExperienceInput | PreferencesInput | NicheInput | Record< string, never >;\r\n\r\nexport interface CurrencyOption {\r\n\tcode: string;\r\n\tname: string;\r\n\tsymbol: string;\r\n}\r\n\r\nexport type FieldErrors = Record< string, string >;\r\n\r\n/** A failed request, reduced to what the screen shows. */\r\nexport interface FailureView {\r\n\tmessage: string;\r\n\t/** 401/403: retrying cannot help. */\r\n\tpermission: boolean;\r\n\tfieldErrors: FieldErrors;\r\n}\r\n","import { __ } from '@wordpress/i18n';\r\nimport { ApiError } from '../../lib/api';\r\nimport {\r\n\tCURRENCY_POSITIONS,\r\n\tEXPERIENCES,\r\n\tNICHES,\r\n\tSTATUSES,\r\n\tSTEP_IDS,\r\n\ttype CurrencyOption,\r\n\ttype Experience,\r\n\ttype FailureView,\r\n\ttype FieldErrors,\r\n\ttype Niche,\r\n\ttype PageAction,\r\n\ttype PageStatus,\r\n\ttype SetupState,\r\n\ttype StarterPage,\r\n\ttype StepId,\r\n\ttype StepInfo,\r\n\ttype StepResponse,\r\n\ttype StepResult,\r\n\ttype StepStatus,\r\n\ttype WizardStatus,\r\n} from './types';\r\n\r\n/** Limits mirrored from the server schema (`SetupSteps`, see contract.json). */\r\nexport const LIMITS = {\r\n\tmaxTopics: 10,\r\n\tmaxTopicChars: 60,\r\n\tmaxDecimals: 8,\r\n} as const;\r\n\r\n// ---- Runtime validation of server data ------------------------------------------------------\r\n\r\nexport function invalidResponse(): ApiError {\r\n\treturn new ApiError( {\r\n\t\tcode: 'invalid_response',\r\n\t\tstatus: 502,\r\n\t\tmessage: __( 'The server returned invalid setup data.', 'ohmylms' ),\r\n\t} );\r\n}\r\n\r\ntype Row = Record< string, unknown >;\r\n\r\nfunction isRow( value: unknown ): value is Row {\r\n\treturn (\r\n\t\t'object' === typeof value && null !== value && ! Array.isArray( value )\r\n\t);\r\n}\r\n\r\nfunction oneOf< T extends string >(\r\n\tlist: readonly T[],\r\n\tvalue: unknown\r\n): T | undefined {\r\n\treturn list.find( ( item ) => item === value );\r\n}\r\n\r\nfunction text( value: unknown ): string {\r\n\tif ( 'string' !== typeof value ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn value;\r\n}\r\n\r\nfunction whole( value: unknown ): number {\r\n\tif ( 'number' !== typeof value || ! Number.isInteger( value ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn value;\r\n}\r\n\r\nfunction nullableText( value: unknown ): string | null {\r\n\treturn null === value ? null : text( value );\r\n}\r\n\r\nfunction asList( value: unknown ): unknown[] {\r\n\tif ( ! Array.isArray( value ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn value;\r\n}\r\n\r\nfunction parseStep( raw: unknown ): StepInfo {\r\n\tif ( ! isRow( raw ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\tconst id = oneOf( STEP_IDS, raw.id );\r\n\tconst status = oneOf< StepStatus >(\r\n\t\t[ 'pending', 'done', 'skipped' ],\r\n\t\traw.status\r\n\t);\r\n\tif (\r\n\t\t! id ||\r\n\t\t! status ||\r\n\t\t'boolean' !== typeof raw.skippable ||\r\n\t\t'boolean' !== typeof raw.available\r\n\t) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn {\r\n\t\tid,\r\n\t\tstatus,\r\n\t\tskippable: raw.skippable,\r\n\t\tavailable: raw.available,\r\n\t};\r\n}\r\n\r\nfunction parsePage( raw: unknown ): StarterPage {\r\n\tif ( ! isRow( raw ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\tconst status = oneOf< PageStatus >(\r\n\t\t[ 'ready', 'adoptable', 'missing' ],\r\n\t\traw.status\r\n\t);\r\n\tif ( ! status ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn {\r\n\t\tkey: text( raw.key ),\r\n\t\ttitle: text( raw.title ),\r\n\t\tslug: text( raw.slug ),\r\n\t\tpage_id: whole( raw.page_id ),\r\n\t\tstatus,\r\n\t};\r\n}\r\n\r\n/**\r\n * Validate the state returned by the server.\r\n *\r\n * @param  raw Decoded JSON.\r\n * @return Typed state.\r\n * @throws {ApiError} `invalid_response` when the shape is wrong.\r\n */\r\nexport function parseState( raw: unknown ): SetupState {\r\n\tif (\r\n\t\t! isRow( raw ) ||\r\n\t\t! isRow( raw.answers ) ||\r\n\t\t! isRow( raw.preferences )\r\n\t) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\tconst status: WizardStatus | undefined = oneOf( STATUSES, raw.status );\r\n\tconst current =\r\n\t\tnull === raw.current_step ? null : oneOf( STEP_IDS, raw.current_step );\r\n\tconst experience =\r\n\t\tnull === raw.answers.experience\r\n\t\t\t? null\r\n\t\t\t: oneOf( EXPERIENCES, raw.answers.experience );\r\n\tconst niche =\r\n\t\tnull === raw.answers.niche ? null : oneOf( NICHES, raw.answers.niche );\r\n\tif (\r\n\t\t! status ||\r\n\t\tundefined === current ||\r\n\t\tundefined === experience ||\r\n\t\tundefined === niche\r\n\t) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn {\r\n\t\tversion: whole( raw.version ),\r\n\t\tstatus,\r\n\t\tcurrentStep: current,\r\n\t\tsteps: asList( raw.steps ).map( parseStep ),\r\n\t\tanswers: {\r\n\t\t\texperience,\r\n\t\t\tniche,\r\n\t\t\ttopics: asList( raw.answers.topics ).map( text ),\r\n\t\t},\r\n\t\tpreferences: {\r\n\t\t\tcurrency: text( raw.preferences.currency ),\r\n\t\t\tcurrency_pos: text( raw.preferences.currency_pos ),\r\n\t\t\tprice_num_decimals: whole( raw.preferences.price_num_decimals ),\r\n\t\t},\r\n\t\tstarterPages: asList( raw.starter_pages ).map( parsePage ),\r\n\t\tstartedAt: nullableText( raw.started_at ),\r\n\t\tcompletedAt: nullableText( raw.completed_at ),\r\n\t};\r\n}\r\n\r\nfunction parseResult( raw: unknown ): StepResult {\r\n\tif ( ! isRow( raw ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn {\r\n\t\tchanged: asList( raw.changed ).map( text ),\r\n\t\tpages: asList( raw.pages ).map( ( item ): PageAction => {\r\n\t\t\tif ( ! isRow( item ) ) {\r\n\t\t\t\tthrow invalidResponse();\r\n\t\t\t}\r\n\t\t\tconst action = oneOf< PageAction[ 'action' ] >(\r\n\t\t\t\t[ 'kept', 'adopted', 'created' ],\r\n\t\t\t\titem.action\r\n\t\t\t);\r\n\t\t\tif ( ! action ) {\r\n\t\t\t\tthrow invalidResponse();\r\n\t\t\t}\r\n\t\t\treturn {\r\n\t\t\t\tkey: text( item.key ),\r\n\t\t\t\tpage_id: whole( item.page_id ),\r\n\t\t\t\taction,\r\n\t\t\t};\r\n\t\t} ),\r\n\t};\r\n}\r\n\r\nexport function parseStepResponse( raw: unknown ): StepResponse {\r\n\tif ( ! isRow( raw ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn {\r\n\t\tstate: parseState( raw.state ),\r\n\t\tresult: parseResult( raw.result ),\r\n\t};\r\n}\r\n\r\n/**\r\n * Validate a wizard-level response (`{ state }`).\r\n *\r\n * @param raw Decoded JSON.\r\n * @return Typed state.\r\n */\r\nexport function parseStateResponse( raw: unknown ): SetupState {\r\n\tif ( ! isRow( raw ) ) {\r\n\t\tthrow invalidResponse();\r\n\t}\r\n\treturn parseState( raw.state );\r\n}\r\n\r\nexport function parseCurrencies( raw: unknown ): CurrencyOption[] {\r\n\treturn asList( raw ).map( ( item ) => {\r\n\t\tif ( ! isRow( item ) ) {\r\n\t\t\tthrow invalidResponse();\r\n\t\t}\r\n\t\treturn {\r\n\t\t\tcode: text( item.code ),\r\n\t\t\tname: text( item.name ),\r\n\t\t\tsymbol: text( item.symbol ),\r\n\t\t};\r\n\t} );\r\n}\r\n\r\n// ---- State machine -------------------------------------------------------------------------\r\n\r\n/**\r\n * Whether a status means the wizard is finished.\r\n * @param state\r\n */\r\nexport function isCompleted( state: SetupState ): boolean {\r\n\treturn 'completed' === state.status;\r\n}\r\n\r\n/** The last screen after all steps, where the wizard is completed. */\r\nexport const FINISH = 'finish';\r\n\r\n/** A wizard screen: a server step or the final review. */\r\nexport type Screen = StepId | typeof FINISH;\r\n\r\n/** Screens in order. */\r\nexport const SCREENS: readonly Screen[] = [ ...STEP_IDS, FINISH ];\r\n\r\n/**\r\n * The screen to show: the one in the URL when it exists, otherwise the first unresolved step, and the\r\n * final screen when everything is resolved.\r\n *\r\n * @param param Raw `step` query parameter.\r\n * @param state Wizard state.\r\n * @return A screen.\r\n */\r\nexport function resolveStep( param: string | null, state: SetupState ): Screen {\r\n\treturn (\r\n\t\tSCREENS.find( ( screen ) => screen === param ) ??\r\n\t\tstate.currentStep ??\r\n\t\tFINISH\r\n\t);\r\n}\r\n\r\nexport function stepIndex( screen: Screen ): number {\r\n\treturn SCREENS.indexOf( screen );\r\n}\r\n\r\n/**\r\n * The screen after `screen`, or `null` at the end.\r\n * @param screen\r\n */\r\nexport function nextStep( screen: Screen ): Screen | null {\r\n\treturn SCREENS[ stepIndex( screen ) + 1 ] ?? null;\r\n}\r\n\r\n/**\r\n * The screen before `screen`, or `null` at the start.\r\n * @param screen\r\n */\r\nexport function previousStep( screen: Screen ): Screen | null {\r\n\tconst index = stepIndex( screen );\r\n\treturn index > 0 ? ( SCREENS[ index - 1 ] ?? null ) : null;\r\n}\r\n\r\nexport function stepInfo(\r\n\tstate: SetupState,\r\n\tstep: StepId\r\n): StepInfo | undefined {\r\n\treturn state.steps.find( ( item ) => item.id === step );\r\n}\r\n\r\n/**\r\n * Done or skipped steps and the total.\r\n * @param state\r\n */\r\nexport function progressOf( state: SetupState ): {\r\n\tresolved: number;\r\n\ttotal: number;\r\n} {\r\n\treturn {\r\n\t\tresolved: state.steps.filter( ( step ) => 'pending' !== step.status )\r\n\t\t\t.length,\r\n\t\ttotal: state.steps.length,\r\n\t};\r\n}\r\n\r\n/**\r\n * Whether the server will accept completion (every step done or skipped).\r\n * @param state\r\n */\r\nexport function canComplete( state: SetupState ): boolean {\r\n\treturn (\r\n\t\tstate.steps.length > 0 &&\r\n\t\tstate.steps.every( ( step ) => 'pending' !== step.status )\r\n\t);\r\n}\r\n\r\n/**\r\n * Ids of the steps still pending.\r\n * @param state\r\n */\r\nexport function pendingSteps( state: SetupState ): StepId[] {\r\n\treturn state.steps\r\n\t\t.filter( ( step ) => 'pending' === step.status )\r\n\t\t.map( ( step ) => step.id );\r\n}\r\n\r\n// ---- Input validation (mirrors the server schema) --------------------------------------------\r\n\r\n/**\r\n * Validate the experience choice.\r\n *\r\n * @param value Chosen value.\r\n * @return Field errors; empty when valid.\r\n */\r\nexport function validateExperience( value: string ): FieldErrors {\r\n\treturn oneOf( EXPERIENCES, value )\r\n\t\t? {}\r\n\t\t: { experience: __( 'Choose an option.', 'ohmylms' ) };\r\n}\r\n\r\nexport function isExperience( value: string ): value is Experience {\r\n\treturn undefined !== oneOf( EXPERIENCES, value );\r\n}\r\n\r\nexport function isNiche( value: string ): value is Niche {\r\n\treturn undefined !== oneOf( NICHES, value );\r\n}\r\n\r\n/**\r\n * Validate the preferences form.\r\n *\r\n * @param input          Form values.\r\n * @param input.currency Currency code.\r\n * @param input.position Symbol position.\r\n * @param input.decimals Number of decimals as typed.\r\n * @return Field errors; empty when valid.\r\n */\r\nexport function validatePreferences( input: {\r\n\tcurrency: string;\r\n\tposition: string;\r\n\tdecimals: string;\r\n} ): FieldErrors {\r\n\tconst errors: FieldErrors = {};\r\n\tif ( ! /^[A-Z]{3}$/.test( input.currency ) ) {\r\n\t\terrors.currency = __( 'Choose a currency.', 'ohmylms' );\r\n\t}\r\n\tif ( ! oneOf( CURRENCY_POSITIONS, input.position ) ) {\r\n\t\terrors.currency_pos = __( 'Choose a position.', 'ohmylms' );\r\n\t}\r\n\tconst decimals = Number( input.decimals );\r\n\tif (\r\n\t\t'' === input.decimals.trim() ||\r\n\t\t! Number.isInteger( decimals ) ||\r\n\t\tdecimals < 0 ||\r\n\t\tdecimals > LIMITS.maxDecimals\r\n\t) {\r\n\t\terrors.price_num_decimals = __(\r\n\t\t\t'Enter a whole number from 0 to 8.',\r\n\t\t\t'ohmylms'\r\n\t\t);\r\n\t}\r\n\treturn errors;\r\n}\r\n\r\n/**\r\n * Split typed topics (one per line or comma separated) into clean, unique names.\r\n *\r\n * @param input Raw text.\r\n * @return Names, in order, without blanks or case-insensitive duplicates.\r\n */\r\nexport function parseTopics( input: string ): string[] {\r\n\tconst seen = new Set< string >();\r\n\tconst names: string[] = [];\r\n\tfor ( const part of input.split( /[\\n,]/ ) ) {\r\n\t\tconst name = part.trim();\r\n\t\tconst key = name.toLowerCase();\r\n\t\tif ( name && ! seen.has( key ) ) {\r\n\t\t\tseen.add( key );\r\n\t\t\tnames.push( name );\r\n\t\t}\r\n\t}\r\n\treturn names;\r\n}\r\n\r\n/**\r\n * Validate the niche form.\r\n *\r\n * @param niche  Chosen niche.\r\n * @param topics Parsed topics.\r\n * @return Field errors; empty when valid.\r\n */\r\nexport function validateNiche( niche: string, topics: string[] ): FieldErrors {\r\n\tconst errors: FieldErrors = {};\r\n\tif ( ! isNiche( niche ) ) {\r\n\t\terrors.niche = __( 'Choose a subject area.', 'ohmylms' );\r\n\t}\r\n\tif ( topics.length > LIMITS.maxTopics ) {\r\n\t\terrors.topics = __( 'Use at most 10 topics.', 'ohmylms' );\r\n\t} else if ( topics.some( ( t ) => t.length > LIMITS.maxTopicChars ) ) {\r\n\t\terrors.topics = __(\r\n\t\t\t'Each topic can have at most 60 characters.',\r\n\t\t\t'ohmylms'\r\n\t\t);\r\n\t}\r\n\treturn errors;\r\n}\r\n\r\n// ---- Failures ------------------------------------------------------------------------------------\r\n\r\nfunction messagesFrom( details: unknown ): FieldErrors {\r\n\tif ( ! isRow( details ) || ! isRow( details.params ) ) {\r\n\t\treturn {};\r\n\t}\r\n\tconst errors: FieldErrors = {};\r\n\tfor ( const [ name, message ] of Object.entries( details.params ) ) {\r\n\t\tif ( 'string' === typeof message ) {\r\n\t\t\terrors[ name ] = message;\r\n\t\t}\r\n\t}\r\n\treturn errors;\r\n}\r\n\r\n/**\r\n * Reduce a failed request to what the screen shows.\r\n *\r\n * @param error Typed API error.\r\n * @return Message, whether it is a permission problem and per-field messages.\r\n */\r\nexport function describeFailure( error: ApiError ): FailureView {\r\n\treturn {\r\n\t\tmessage: error.message,\r\n\t\tpermission: 401 === error.status || 403 === error.status,\r\n\t\tfieldErrors: messagesFrom( error.details ),\r\n\t};\r\n}\r\n","import { get, post } from '../../lib/api';\r\nimport {\r\n\tparseCurrencies,\r\n\tparseState,\r\n\tparseStateResponse,\r\n\tparseStepResponse,\r\n} from './model';\r\nimport type {\r\n\tCurrencyOption,\r\n\tSetupState,\r\n\tStepId,\r\n\tStepInput,\r\n\tStepResponse,\r\n} from './types';\r\n\r\nconst BASE = '/ohmylms/v1/setup';\r\n\r\n/**\r\n * Load the wizard state.\r\n *\r\n * @param signal Cancels the request.\r\n * @return Validated state.\r\n */\r\nexport async function getSetup( signal?: AbortSignal ): Promise< SetupState > {\r\n\treturn parseState( await get< unknown >( BASE, { signal } ) );\r\n}\r\n\r\n/**\r\n * Save a step and mark it done.\r\n *\r\n * @param step   Step id.\r\n * @param input  Step input (empty object for steps without fields).\r\n * @param signal Cancels the request.\r\n * @return New state and the step result.\r\n */\r\nexport async function saveStep(\r\n\tstep: StepId,\r\n\tinput: StepInput,\r\n\tsignal?: AbortSignal\r\n): Promise< StepResponse > {\r\n\treturn parseStepResponse(\r\n\t\tawait post< unknown >( `${ BASE }/steps/${ step }`, input, { signal } )\r\n\t);\r\n}\r\n\r\n/**\r\n * Skip a step.\r\n *\r\n * @param step   Step id.\r\n * @param signal Cancels the request.\r\n * @return New state and an empty step result.\r\n */\r\nexport async function skipStep(\r\n\tstep: StepId,\r\n\tsignal?: AbortSignal\r\n): Promise< StepResponse > {\r\n\treturn parseStepResponse(\r\n\t\tawait post< unknown >( `${ BASE }/steps/${ step }/skip`, undefined, {\r\n\t\t\tsignal,\r\n\t\t} )\r\n\t);\r\n}\r\n\r\n/**\r\n * Complete the wizard.\r\n *\r\n * @param signal Cancels the request.\r\n * @return New state.\r\n */\r\nexport async function completeSetup(\r\n\tsignal?: AbortSignal\r\n): Promise< SetupState > {\r\n\treturn parseStateResponse(\r\n\t\tawait post< unknown >( `${ BASE }/complete`, undefined, { signal } )\r\n\t);\r\n}\r\n\r\n/**\r\n * Leave the wizard without completing it.\r\n *\r\n * @param step   The step the user was on.\r\n * @param signal Cancels the request.\r\n * @return New state.\r\n */\r\nexport async function dismissSetup(\r\n\tstep: StepId | null,\r\n\tsignal?: AbortSignal\r\n): Promise< SetupState > {\r\n\treturn parseStateResponse(\r\n\t\tawait post< unknown >( `${ BASE }/dismiss`, step ? { step } : {}, {\r\n\t\t\tsignal,\r\n\t\t} )\r\n\t);\r\n}\r\n\r\n/**\r\n * Start the wizard over (progress only).\r\n *\r\n * @param signal Cancels the request.\r\n * @return New state.\r\n */\r\nexport async function resetSetup(\r\n\tsignal?: AbortSignal\r\n): Promise< SetupState > {\r\n\treturn parseStateResponse(\r\n\t\tawait post< unknown >( `${ BASE }/reset`, undefined, { signal } )\r\n\t);\r\n}\r\n\r\n/**\r\n * List currencies for the preferences step (settings API, same capability).\r\n *\r\n * @param signal Cancels the request.\r\n * @return Currencies.\r\n */\r\nexport async function listCurrencies(\r\n\tsignal?: AbortSignal\r\n): Promise< CurrencyOption[] > {\r\n\treturn parseCurrencies(\r\n\t\tawait get< unknown >( '/ohmylms/v1/settings/currencies', { signal } )\r\n\t);\r\n}\r\n","import { __, sprintf } from '@wordpress/i18n';\r\nimport { FINISH, SCREENS, stepIndex, type Screen } from './model';\r\nimport type { SetupState, StepStatus } from './types';\r\n\r\n/**\r\n * Translated names of the screens.\r\n * @param screen\r\n */\r\nexport function screenLabel( screen: Screen ): string {\r\n\tswitch ( screen ) {\r\n\t\tcase 'welcome':\r\n\t\t\treturn __( 'Welcome', 'ohmylms' );\r\n\t\tcase 'experience':\r\n\t\t\treturn __( 'Experience', 'ohmylms' );\r\n\t\tcase 'preferences':\r\n\t\t\treturn __( 'Preferences', 'ohmylms' );\r\n\t\tcase 'niche':\r\n\t\t\treturn __( 'Subject area', 'ohmylms' );\r\n\t\tcase 'pages':\r\n\t\t\treturn __( 'Starter pages', 'ohmylms' );\r\n\t\tcase 'import':\r\n\t\t\treturn __( 'Import courses', 'ohmylms' );\r\n\t\tcase FINISH:\r\n\t\t\treturn __( 'Finish', 'ohmylms' );\r\n\t}\r\n}\r\n\r\nfunction statusText( status: StepStatus | undefined ): string {\r\n\tif ( 'done' === status ) {\r\n\t\treturn __( 'done', 'ohmylms' );\r\n\t}\r\n\tif ( 'skipped' === status ) {\r\n\t\treturn __( 'skipped', 'ohmylms' );\r\n\t}\r\n\treturn '';\r\n}\r\n\r\n/**\r\n * Progress through the wizard. Every screen is a button (all steps can be revisited), the current one\r\n * has `aria-current=\"step\"`, and a polite live region announces \"Step N of M: name\" when it changes.\r\n *\r\n * @param props          Component props.\r\n * @param props.setup    Wizard state, for the done/skipped markers.\r\n * @param props.current  Current screen.\r\n * @param props.onSelect Called with the screen to open.\r\n * @param props.disabled Disable navigation while a request is pending.\r\n */\r\nexport function Stepper( {\r\n\tsetup,\r\n\tcurrent,\r\n\tonSelect,\r\n\tdisabled,\r\n}: {\r\n\tsetup: SetupState;\r\n\tcurrent: Screen;\r\n\tonSelect: ( screen: Screen ) => void;\r\n\tdisabled: boolean;\r\n} ) {\r\n\treturn (\r\n\t\t<>\r\n\t\t\t<p role=\"status\" className=\"screen-reader-text\">\r\n\t\t\t\t{ sprintf(\r\n\t\t\t\t\t/* translators: 1: step number, 2: number of steps, 3: step name. */\r\n\t\t\t\t\t__( 'Step %1$d of %2$d: %3$s', 'ohmylms' ),\r\n\t\t\t\t\tstepIndex( current ) + 1,\r\n\t\t\t\t\tSCREENS.length,\r\n\t\t\t\t\tscreenLabel( current )\r\n\t\t\t\t) }\r\n\t\t\t</p>\r\n\t\t\t<nav aria-label={ __( 'Setup progress', 'ohmylms' ) }>\r\n\t\t\t\t<ol className=\"ohmylms-setup-steps\">\r\n\t\t\t\t\t{ SCREENS.map( ( screen ) => {\r\n\t\t\t\t\t\tconst info = setup.steps.find(\r\n\t\t\t\t\t\t\t( s ) => s.id === screen\r\n\t\t\t\t\t\t);\r\n\t\t\t\t\t\tconst marker = statusText( info?.status );\r\n\t\t\t\t\t\treturn (\r\n\t\t\t\t\t\t\t<li key={ screen }>\r\n\t\t\t\t\t\t\t\t<button\r\n\t\t\t\t\t\t\t\t\ttype=\"button\"\r\n\t\t\t\t\t\t\t\t\tclassName=\"button-link\"\r\n\t\t\t\t\t\t\t\t\taria-current={\r\n\t\t\t\t\t\t\t\t\t\tscreen === current ? 'step' : undefined\r\n\t\t\t\t\t\t\t\t\t}\r\n\t\t\t\t\t\t\t\t\tdisabled={ disabled }\r\n\t\t\t\t\t\t\t\t\tonClick={ () => onSelect( screen ) }\r\n\t\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t\t<span>{ screenLabel( screen ) }</span>\r\n\t\t\t\t\t\t\t\t\t{ marker && (\r\n\t\t\t\t\t\t\t\t\t\t<span className=\"screen-reader-text\">\r\n\t\t\t\t\t\t\t\t\t\t\t{ ` (${ marker })` }\r\n\t\t\t\t\t\t\t\t\t\t</span>\r\n\t\t\t\t\t\t\t\t\t) }\r\n\t\t\t\t\t\t\t\t</button>\r\n\t\t\t\t\t\t\t\t{ marker && (\r\n\t\t\t\t\t\t\t\t\t<span aria-hidden=\"true\">{ ' ✓' }</span>\r\n\t\t\t\t\t\t\t\t) }\r\n\t\t\t\t\t\t\t</li>\r\n\t\t\t\t\t\t);\r\n\t\t\t\t\t} ) }\r\n\t\t\t\t</ol>\r\n\t\t\t</nav>\r\n\t\t</>\r\n\t);\r\n}\r\n","import { Button, Notice } from '@wordpress/components';\r\nimport { useEffect, useRef } from '@wordpress/element';\r\nimport type { ReactNode } from 'react';\r\nimport { __ } from '@wordpress/i18n';\r\nimport type { FailureView } from './types';\r\n\r\n/**\r\n * Shared chrome of a step: heading (focused when the step opens, so screen readers announce it), the\r\n * error of the last action, the form and Back / Skip / Continue controls. Submit with Enter works\r\n * because the controls live in a real form.\r\n *\r\n * @param props             Component props.\r\n * @param props.title       Step heading.\r\n * @param props.description Short intro.\r\n * @param props.busy        An action is pending.\r\n * @param props.error       Failure of the last action.\r\n * @param props.onSubmit    Continue / save handler.\r\n * @param props.submitLabel Label of the primary button.\r\n * @param props.onBack      Back handler; omit on the first step.\r\n * @param props.onSkip      Skip handler; omit when the step cannot be skipped.\r\n * @param props.children    The fields.\r\n */\r\nexport function StepFrame( {\r\n\ttitle,\r\n\tdescription,\r\n\tbusy,\r\n\terror,\r\n\tonSubmit,\r\n\tsubmitLabel,\r\n\tonBack,\r\n\tonSkip,\r\n\tchildren,\r\n}: {\r\n\ttitle: string;\r\n\tdescription: string;\r\n\tbusy: boolean;\r\n\terror: FailureView | null;\r\n\tonSubmit: () => void;\r\n\tsubmitLabel: string;\r\n\tonBack?: () => void;\r\n\tonSkip?: () => void;\r\n\tchildren?: ReactNode;\r\n} ) {\r\n\tconst heading = useRef< HTMLHeadingElement >( null );\r\n\tuseEffect( () => {\r\n\t\theading.current?.focus();\r\n\t}, [ title ] );\r\n\r\n\treturn (\r\n\t\t<form\r\n\t\t\taria-labelledby=\"ohmylms-setup-heading\"\r\n\t\t\tnoValidate\r\n\t\t\tonSubmit={ ( event ) => {\r\n\t\t\t\tevent.preventDefault();\r\n\t\t\t\tif ( ! busy ) {\r\n\t\t\t\t\tonSubmit();\r\n\t\t\t\t}\r\n\t\t\t} }\r\n\t\t>\r\n\t\t\t<h3 id=\"ohmylms-setup-heading\" ref={ heading } tabIndex={ -1 }>\r\n\t\t\t\t{ title }\r\n\t\t\t</h3>\r\n\t\t\t<p>{ description }</p>\r\n\t\t\t{ error && (\r\n\t\t\t\t<Notice status=\"error\" isDismissible={ false }>\r\n\t\t\t\t\t{ error.message }\r\n\t\t\t\t</Notice>\r\n\t\t\t) }\r\n\t\t\t{ children }\r\n\t\t\t<p>\r\n\t\t\t\t{ onBack && (\r\n\t\t\t\t\t<Button\r\n\t\t\t\t\t\tvariant=\"tertiary\"\r\n\t\t\t\t\t\tonClick={ onBack }\r\n\t\t\t\t\t\tdisabled={ busy }\r\n\t\t\t\t\t\taccessibleWhenDisabled\r\n\t\t\t\t\t>\r\n\t\t\t\t\t\t{ __( 'Back', 'ohmylms' ) }\r\n\t\t\t\t\t</Button>\r\n\t\t\t\t) }\r\n\t\t\t\t{ onSkip && (\r\n\t\t\t\t\t<Button\r\n\t\t\t\t\t\tvariant=\"secondary\"\r\n\t\t\t\t\t\tonClick={ onSkip }\r\n\t\t\t\t\t\tdisabled={ busy }\r\n\t\t\t\t\t\taccessibleWhenDisabled\r\n\t\t\t\t\t>\r\n\t\t\t\t\t\t{ __( 'Skip this step', 'ohmylms' ) }\r\n\t\t\t\t\t</Button>\r\n\t\t\t\t) }{ ' ' }\r\n\t\t\t\t<Button\r\n\t\t\t\t\tvariant=\"primary\"\r\n\t\t\t\t\ttype=\"submit\"\r\n\t\t\t\t\tisBusy={ busy }\r\n\t\t\t\t\tdisabled={ busy }\r\n\t\t\t\t\taccessibleWhenDisabled\r\n\t\t\t\t>\r\n\t\t\t\t\t{ busy ? __( 'Saving…', 'ohmylms' ) : submitLabel }\r\n\t\t\t\t</Button>\r\n\t\t\t</p>\r\n\t\t</form>\r\n\t);\r\n}\r\n","import {\r\n\tRadioControl,\r\n\tSelectControl,\r\n\tSpinner,\r\n\tTextControl,\r\n\tTextareaControl,\r\n} from '@wordpress/components';\r\nimport { useEffect, useState } from '@wordpress/element';\r\nimport { __, sprintf } from '@wordpress/i18n';\r\nimport { normalizeApiError } from '../../lib/api';\r\nimport { listCurrencies } from './api';\r\nimport {\r\n\tdescribeFailure,\r\n\tisExperience,\r\n\tisNiche,\r\n\tparseTopics,\r\n\tvalidateExperience,\r\n\tvalidateNiche,\r\n\tvalidatePreferences,\r\n} from './model';\r\nimport { StepFrame } from './StepFrame';\r\nimport type {\r\n\tCurrencyOption,\r\n\tCurrencyPosition,\r\n\tFailureView,\r\n\tFieldErrors,\r\n\tSetupState,\r\n\tStepInput,\r\n} from './types';\r\n\r\n/** Props shared by every step form. */\r\nexport interface StepProps {\r\n\tsetup: SetupState;\r\n\tbusy: boolean;\r\n\terror: FailureView | null;\r\n\t/** Save the step with this input. */\r\n\tonSubmit: ( input: StepInput ) => void;\r\n\tonBack?: () => void;\r\n\tonSkip?: () => void;\r\n}\r\n\r\nconst empty: Record< string, never > = {};\r\n\r\nexport function WelcomeStep( { busy, error, onSubmit, onSkip }: StepProps ) {\r\n\treturn (\r\n\t\t<StepFrame\r\n\t\t\ttitle={ __( 'Welcome to OhMyLMS', 'ohmylms' ) }\r\n\t\t\tdescription={ __(\r\n\t\t\t\t'A few short steps set up your site preferences and the pages students need. You can change everything later in Settings, and you can leave at any time.',\r\n\t\t\t\t'ohmylms'\r\n\t\t\t) }\r\n\t\t\tbusy={ busy }\r\n\t\t\terror={ error }\r\n\t\t\tonSubmit={ () => onSubmit( empty ) }\r\n\t\t\tonSkip={ onSkip }\r\n\t\t\tsubmitLabel={ __( 'Start setup', 'ohmylms' ) }\r\n\t\t/>\r\n\t);\r\n}\r\n\r\nexport function ExperienceStep( {\r\n\tsetup,\r\n\tbusy,\r\n\terror,\r\n\tonSubmit,\r\n\tonBack,\r\n}: StepProps ) {\r\n\tconst [ value, setValue ] = useState< string >(\r\n\t\tsetup.answers.experience ?? ''\r\n\t);\r\n\tconst [ errors, setErrors ] = useState< FieldErrors >( {} );\r\n\tconst message = errors.