t":["/** Step ids in wizard order. Mirrors `SetupSteps::ids()` (see contract.json). */\nexport const STEP_IDS = [\n\t'welcome',\n\t'experience',\n\t'preferences',\n\t'niche',\n\t'pages',\n\t'import',\n] as const;\nexport type StepId = ( typeof STEP_IDS )[ number ];\n\nexport const EXPERIENCES = [\n\t'beginner',\n\t'intermediate',\n\t'experienced',\n] as const;\nexport type Experience = ( typeof EXPERIENCES )[ number ];\n\nexport const NICHES = [\n\t'digital-marketing-growth',\n\t'tech-skills',\n\t'creator-economy',\n\t'academic-test-prep',\n\t'other',\n] as const;\nexport type Niche = ( typeof NICHES )[ number ];\n\nexport const CURRENCY_POSITIONS = [\n\t'left',\n\t'right',\n\t'left_space',\n\t'right_space',\n] as const;\nexport type CurrencyPosition = ( typeof CURRENCY_POSITIONS )[ number ];\n\nexport const STATUSES = [\n\t'not_started',\n\t'in_progress',\n\t'completed',\n\t'dismissed',\n] as const;\nexport type WizardStatus = ( typeof STATUSES )[ number ];\n\nexport type StepStatus = 'pending' | 'done' | 'skipped';\n\nexport interface StepInfo {\n\tid: StepId;\n\tstatus: StepStatus;\n\tskippable: boolean;\n\tavailable: boolean;\n}\n\nexport type PageStatus = 'ready' | 'adoptable' | 'missing';\n\nexport interface StarterPage {\n\tkey: string;\n\ttitle: string;\n\tslug: string;\n\tpage_id: number;\n\tstatus: PageStatus;\n}\n\nexport interface Preferences {\n\tcurrency: string;\n\tcurrency_pos: string;\n\tprice_num_decimals: number;\n}\n\nexport interface SetupState {\n\tversion: number;\n\tstatus: WizardStatus;\n\tcurrentStep: StepId | null;\n\tsteps: StepInfo[];\n\tanswers: {\n\t\texperience: Experience | null;\n\t\tniche: Niche | null;\n\t\ttopics: string[];\n\t};\n\tpreferences: Preferences;\n\tstarterPages: StarterPage[];\n\tstartedAt: string | null;\n\tcompletedAt: string | null;\n}\n\nexport interface PageAction {\n\tkey: string;\n\tpage_id: number;\n\taction: 'kept' | 'adopted' | 'created';\n}\n\nexport interface StepResult {\n\tchanged: string[];\n\tpages: PageAction[];\n}\n\nexport interface StepResponse {\n\tstate: SetupState;\n\tresult: StepResult;\n}\n\n/** Body of a step request. */\nexport interface ExperienceInput {\n\texperience: Experience;\n}\nexport interface PreferencesInput {\n\tcurrency: string;\n\tcurrency_pos: CurrencyPosition;\n\tprice_num_decimals: number;\n}\nexport interface NicheInput {\n\tniche: Niche;\n\ttopics: string[];\n}\nexport type StepInput =\n\tExperienceInput | PreferencesInput | NicheInput | Record< string, never >;\n\nexport interface CurrencyOption {\n\tcode: string;\n\tname: string;\n\tsymbol: string;\n}\n\nexport type FieldErrors = Record< string, string >;\n\n/** A failed request, reduced to what the screen shows. */\nexport interface FailureView {\n\tmessage: string;\n\t/** 401/403: retrying cannot help. */\n\tpermission: boolean;\n\tfieldErrors: FieldErrors;\n}\n","import { __ } from '@wordpress/i18n';\nimport { ApiError } from '../../lib/api';\nimport {\n\tCURRENCY_POSITIONS,\n\tEXPERIENCES,\n\tNICHES,\n\tSTATUSES,\n\tSTEP_IDS,\n\ttype CurrencyOption,\n\ttype Experience,\n\ttype FailureView,\n\ttype FieldErrors,\n\ttype Niche,\n\ttype PageAction,\n\ttype PageStatus,\n\ttype SetupState,\n\ttype StarterPage,\n\ttype StepId,\n\ttype StepInfo,\n\ttype StepResponse,\n\ttype StepResult,\n\ttype StepStatus,\n\ttype WizardStatus,\n} from './types';\n\n/** Limits mirrored from the server schema (`SetupSteps`, see contract.json). */\nexport const LIMITS = {\n\tmaxTopics: 10,\n\tmaxTopicChars: 60,\n\tmaxDecimals: 8,\n} as const;\n\n// ---- Runtime validation of server data ------------------------------------------------------\n\nexport function invalidResponse(): ApiError {\n\treturn new ApiError( {\n\t\tcode: 'invalid_response',\n\t\tstatus: 502,\n\t\tmessage: __( 'The server returned invalid setup data.', 'ohmylms' ),\n\t} );\n}\n\ntype Row = Record< string, unknown >;\n\nfunction isRow( value: unknown ): value is Row {\n\treturn (\n\t\t'object' === typeof value && null !== value && ! Array.isArray( value )\n\t);\n}\n\nfunction oneOf< T extends string >(\n\tlist: readonly T[],\n\tvalue: unknown\n): T | undefined {\n\treturn list.find( ( item ) => item === value );\n}\n\nfunction text( value: unknown ): string {\n\tif ( 'string' !== typeof value ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn value;\n}\n\nfunction whole( value: unknown ): number {\n\tif ( 'number' !== typeof value || ! Number.isInteger( value ) ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn value;\n}\n\nfunction nullableText( value: unknown ): string | null {\n\treturn null === value ? null : text( value );\n}\n\nfunction asList( value: unknown ): unknown[] {\n\tif ( ! Array.isArray( value ) ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn value;\n}\n\nfunction parseStep( raw: unknown ): StepInfo {\n\tif ( ! isRow( raw ) ) {\n\t\tthrow invalidResponse();\n\t}\n\tconst id = oneOf( STEP_IDS, raw.id );\n\tconst status = oneOf< StepStatus >(\n\t\t[ 'pending', 'done', 'skipped' ],\n\t\traw.status\n\t);\n\tif (\n\t\t! id ||\n\t\t! status ||\n\t\t'boolean' !== typeof raw.skippable ||\n\t\t'boolean' !== typeof raw.available\n\t) {\n\t\tthrow invalidResponse();\n\t}\n\treturn {\n\t\tid,\n\t\tstatus,\n\t\tskippable: raw.skippable,\n\t\tavailable: raw.available,\n\t};\n}\n\nfunction parsePage( raw: unknown ): StarterPage {\n\tif ( ! isRow( raw ) ) {\n\t\tthrow invalidResponse();\n\t}\n\tconst status = oneOf< PageStatus >(\n\t\t[ 'ready', 'adoptable', 'missing' ],\n\t\traw.status\n\t);\n\tif ( ! status ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn {\n\t\tkey: text( raw.key ),\n\t\ttitle: text( raw.title ),\n\t\tslug: text( raw.slug ),\n\t\tpage_id: whole( raw.page_id ),\n\t\tstatus,\n\t};\n}\n\n/**\n * Validate the state returned by the server.\n *\n * @param  raw Decoded JSON.\n * @return Typed state.\n * @throws {ApiError} `invalid_response` when the shape is wrong.\n */\nexport function parseState( raw: unknown ): SetupState {\n\tif (\n\t\t! isRow( raw ) ||\n\t\t! isRow( raw.answers ) ||\n\t\t! isRow( raw.preferences )\n\t) {\n\t\tthrow invalidResponse();\n\t}\n\tconst status: WizardStatus | undefined = oneOf( STATUSES, raw.status );\n\tconst current =\n\t\tnull === raw.current_step ? null : oneOf( STEP_IDS, raw.current_step );\n\tconst experience =\n\t\tnull === raw.answers.experience\n\t\t\t? null\n\t\t\t: oneOf( EXPERIENCES, raw.answers.experience );\n\tconst niche =\n\t\tnull === raw.answers.niche ? null : oneOf( NICHES, raw.answers.niche );\n\tif (\n\t\t! status ||\n\t\tundefined === current ||\n\t\tundefined === experience ||\n\t\tundefined === niche\n\t) {\n\t\tthrow invalidResponse();\n\t}\n\treturn {\n\t\tversion: whole( raw.version ),\n\t\tstatus,\n\t\tcurrentStep: current,\n\t\tsteps: asList( raw.steps ).map( parseStep ),\n\t\tanswers: {\n\t\t\texperience,\n\t\t\tniche,\n\t\t\ttopics: asList( raw.answers.topics ).map( text ),\n\t\t},\n\t\tpreferences: {\n\t\t\tcurrency: text( raw.preferences.currency ),\n\t\t\tcurrency_pos: text( raw.preferences.currency_pos ),\n\t\t\tprice_num_decimals: whole( raw.preferences.price_num_decimals ),\n\t\t},\n\t\tstarterPages: asList( raw.starter_pages ).map( parsePage ),\n\t\tstartedAt: nullableText( raw.started_at ),\n\t\tcompletedAt: nullableText( raw.completed_at ),\n\t};\n}\n\nfunction parseResult( raw: unknown ): StepResult {\n\tif ( ! isRow( raw ) ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn {\n\t\tchanged: asList( raw.changed ).map( text ),\n\t\tpages: asList( raw.pages ).map( ( item ): PageAction => {\n\t\t\tif ( ! isRow( item ) ) {\n\t\t\t\tthrow invalidResponse();\n\t\t\t}\n\t\t\tconst action = oneOf< PageAction[ 'action' ] >(\n\t\t\t\t[ 'kept', 'adopted', 'created' ],\n\t\t\t\titem.action\n\t\t\t);\n\t\t\tif ( ! action ) {\n\t\t\t\tthrow invalidResponse();\n\t\t\t}\n\t\t\treturn {\n\t\t\t\tkey: text( item.key ),\n\t\t\t\tpage_id: whole( item.page_id ),\n\t\t\t\taction,\n\t\t\t};\n\t\t} ),\n\t};\n}\n\nexport function parseStepResponse( raw: unknown ): StepResponse {\n\tif ( ! isRow( raw ) ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn {\n\t\tstate: parseState( raw.state ),\n\t\tresult: parseResult( raw.result ),\n\t};\n}\n\n/**\n * Validate a wizard-level response (`{ state }`).\n *\n * @param raw Decoded JSON.\n * @return Typed state.\n */\nexport function parseStateResponse( raw: unknown ): SetupState {\n\tif ( ! isRow( raw ) ) {\n\t\tthrow invalidResponse();\n\t}\n\treturn parseState( raw.state );\n}\n\nexport function parseCurrencies( raw: unknown ): CurrencyOption[] {\n\treturn asList( raw ).map( ( item ) => {\n\t\tif ( ! isRow( item ) ) {\n\t\t\tthrow invalidResponse();\n\t\t}\n\t\treturn {\n\t\t\tcode: text( item.code ),\n\t\t\tname: text( item.name ),\n\t\t\tsymbol: text( item.symbol ),\n\t\t};\n\t} );\n}\n\n// ---- State machine -------------------------------------------------------------------------\n\n/**\n * Whether a status means the wizard is finished.\n * @param state\n */\nexport function isCompleted( state: SetupState ): boolean {\n\treturn 'completed' === state.status;\n}\n\n/** The last screen after all steps, where the wizard is completed. */\nexport const FINISH = 'finish';\n\n/** A wizard screen: a server step or the final review. */\nexport type Screen = StepId | typeof FINISH;\n\n/** Screens in order. */\nexport const SCREENS: readonly Screen[] = [ ...STEP_IDS, FINISH ];\n\n/**\n * The screen to show: the one in the URL when it exists, otherwise the first unresolved step, and the\n * final screen when everything is resolved.\n *\n * @param param Raw `step` query parameter.\n * @param state Wizard state.\n * @return A screen.\n */\nexport function resolveStep( param: string | null, state: SetupState ): Screen {\n\treturn (\n\t\tSCREENS.find( ( screen ) => screen === param ) ??\n\t\tstate.currentStep ??\n\t\tFINISH\n\t);\n}\n\nexport function stepIndex( screen: Screen ): number {\n\treturn SCREENS.indexOf( screen );\n}\n\n/**\n * The screen after `screen`, or `null` at the end.\n * @param screen\n */\nexport function nextStep( screen: Screen ): Screen | null {\n\treturn SCREENS[ stepIndex( screen ) + 1 ] ?? null;\n}\n\n/**\n * The screen before `screen`, or `null` at the start.\n * @param screen\n */\nexport function previousStep( screen: Screen ): Screen | null {\n\tconst index = stepIndex( screen );\n\treturn index > 0 ? ( SCREENS[ index - 1 ] ?? null ) : null;\n}\n\nexport function stepInfo(\n\tstate: SetupState,\n\tstep: StepId\n): StepInfo | undefined {\n\treturn state.steps.find( ( item ) => item.id === step );\n}\n\n/**\n * Done or skipped steps and the total.\n * @param state\n */\nexport function progressOf( state: SetupState ): {\n\tresolved: number;\n\ttotal: number;\n} {\n\treturn {\n\t\tresolved: state.steps.filter( ( step ) => 'pending' !== step.status )\n\t\t\t.length,\n\t\ttotal: state.steps.length,\n\t};\n}\n\n/**\n * Whether the server will accept completion (every step done or skipped).\n * @param state\n */\nexport function canComplete( state: SetupState ): boolean {\n\treturn (\n\t\tstate.steps.length > 0 &&\n\t\tstate.steps.every( ( step ) => 'pending' !== step.status )\n\t);\n}\n\n/**\n * Ids of the steps still pending.\n * @param state\n */\nexport function pendingSteps( state: SetupState ): StepId[] {\n\treturn state.steps\n\t\t.filter( ( step ) => 'pending' === step.status )\n\t\t.map( ( step ) => step.id );\n}\n\n// ---- Input validation (mirrors the server schema) --------------------------------------------\n\n/**\n * Validate the experience choice.\n *\n * @param value Chosen value.\n * @return Field errors; empty when valid.\n */\nexport function validateExperience( value: string ): FieldErrors {\n\treturn oneOf( EXPERIENCES, value )\n\t\t? {}\n\t\t: { experience: __( 'Choose an option.', 'ohmylms' ) };\n}\n\nexport function isExperience( value: string ): value is Experience {\n\treturn undefined !== oneOf( EXPERIENCES, value );\n}\n\nexport function isNiche( value: string ): value is Niche {\n\treturn undefined !== oneOf( NICHES, value );\n}\n\n/**\n * Validate the preferences form.\n *\n * @param input          Form values.\n * @param input.currency Currency code.\n * @param input.position Symbol position.\n * @param input.decimals Number of decimals as typed.\n * @return Field errors; empty when valid.\n */\nexport function validatePreferences( input: {\n\tcurrency: string;\n\tposition: string;\n\tdecimals: string;\n} ): FieldErrors {\n\tconst errors: FieldErrors = {};\n\tif ( ! /^[A-Z]{3}$/.test( input.currency ) ) {\n\t\terrors.currency = __( 'Choose a currency.', 'ohmylms' );\n\t}\n\tif ( ! oneOf( CURRENCY_POSITIONS, input.position ) ) {\n\t\terrors.currency_pos = __( 'Choose a position.', 'ohmylms' );\n\t}\n\tconst decimals = Number( input.decimals );\n\tif (\n\t\t'' === input.decimals.trim() ||\n\t\t! Number.isInteger( decimals ) ||\n\t\tdecimals < 0 ||\n\t\tdecimals > LIMITS.maxDecimals\n\t) {\n\t\terrors.price_num_decimals = __(\n\t\t\t'Enter a whole number from 0 to 8.',\n\t\t\t'ohmylms'\n\t\t);\n\t}\n\treturn errors;\n}\n\n/**\n * Split typed topics (one per line or comma separated) into clean, unique names.\n *\n * @param input Raw text.\n * @return Names, in order, without blanks or case-insensitive duplicates.\n */\nexport function parseTopics( input: string ): string[] {\n\tconst seen = new Set< string >();\n\tconst names: string[] = [];\n\tfor ( const part of input.split( /[\\n,]/ ) ) {\n\t\tconst name = part.trim();\n\t\tconst key = name.toLowerCase();\n\t\tif ( name && ! seen.has( key ) ) {\n\t\t\tseen.add( key );\n\t\t\tnames.push( name );\n\t\t}\n\t}\n\treturn names;\n}\n\n/**\n * Validate the niche form.\n *\n * @param niche  Chosen niche.\n * @param topics Parsed topics.\n * @return Field errors; empty when valid.\n */\nexport function validateNiche( niche: string, topics: string[] ): FieldErrors {\n\tconst errors: FieldErrors = {};\n\tif ( ! isNiche( niche ) ) {\n\t\terrors.niche = __( 'Choose a subject area.', 'ohmylms' );\n\t}\n\tif ( topics.length > LIMITS.maxTopics ) {\n\t\terrors.topics = __( 'Use at most 10 topics.', 'ohmylms' );\n\t} else if ( topics.some( ( t ) => t.length > LIMITS.maxTopicChars ) ) {\n\t\terrors.topics = __(\n\t\t\t'Each topic can have at most 60 characters.',\n\t\t\t'ohmylms'\n\t\t);\n\t}\n\treturn errors;\n}\n\n// ---- Failures ------------------------------------------------------------------------------------\n\nfunction messagesFrom( details: unknown ): FieldErrors {\n\tif ( ! isRow( details ) || ! isRow( details.params ) ) {\n\t\treturn {};\n\t}\n\tconst errors: FieldErrors = {};\n\tfor ( const [ name, message ] of Object.entries( details.params ) ) {\n\t\tif ( 'string' === typeof message ) {\n\t\t\terrors[ name ] = message;\n\t\t}\n\t}\n\treturn errors;\n}\n\n/**\n * Reduce a failed request to what the screen shows.\n *\n * @param error Typed API error.\n * @return Message, whether it is a permission problem and per-field messages.\n */\nexport function describeFailure( error: ApiError ): FailureView {\n\treturn {\n\t\tmessage: error.message,\n\t\tpermission: 401 === error.status || 403 === error.status,\n\t\tfieldErrors: messagesFrom( error.details ),\n\t};\n}\n","import { get, post } from '../../lib/api';\nimport {\n\tparseCurrencies,\n\tparseState,\n\tparseStateResponse,\n\tparseStepResponse,\n} from './model';\nimport type {\n\tCurrencyOption,\n\tSetupState,\n\tStepId,\n\tStepInput,\n\tStepResponse,\n} from './types';\n\nconst BASE = '/ohmylms/v1/setup';\n\n/**\n * Load the wizard state.\n *\n * @param signal Cancels the request.\n * @return Validated state.\n */\nexport async function getSetup( signal?: AbortSignal ): Promise< SetupState > {\n\treturn parseState( await get< unknown >( BASE, { signal } ) );\n}\n\n/**\n * Save a step and mark it done.\n *\n * @param step   Step id.\n * @param input  Step input (empty object for steps without fields).\n * @param signal Cancels the request.\n * @return New state and the step result.\n */\nexport async function saveStep(\n\tstep: StepId,\n\tinput: StepInput,\n\tsignal?: AbortSignal\n): Promise< StepResponse > {\n\treturn parseStepResponse(\n\t\tawait post< unknown >( `${ BASE }/steps/${ step }`, input, { signal } )\n\t);\n}\n\n/**\n * Skip a step.\n *\n * @param step   Step id.\n * @param signal Cancels the request.\n * @return New state and an empty step result.\n */\nexport async function skipStep(\n\tstep: StepId,\n\tsignal?: AbortSignal\n): Promise< StepResponse > {\n\treturn parseStepResponse(\n\t\tawait post< unknown >( `${ BASE }/steps/${ step }/skip`, undefined, {\n\t\t\tsignal,\n\t\t} )\n\t);\n}\n\n/**\n * Complete the wizard.\n *\n * @param signal Cancels the request.\n * @return New state.\n */\nexport async function completeSetup(\n\tsignal?: AbortSignal\n): Promise< SetupState > {\n\treturn parseStateResponse(\n\t\tawait post< unknown >( `${ BASE }/complete`, undefined, { signal } )\n\t);\n}\n\n/**\n * Leave the wizard without completing it.\n *\n * @param step   The step the user was on.\n * @param signal Cancels the request.\n * @return New state.\n */\nexport async function dismissSetup(\n\tstep: StepId | null,\n\tsignal?: AbortSignal\n): Promise< SetupState > {\n\treturn parseStateResponse(\n\t\tawait post< unknown >( `${ BASE }/dismiss`, step ? { step } : {}, {\n\t\t\tsignal,\n\t\t} )\n\t);\n}\n\n/**\n * Start the wizard over (progress only).\n *\n * @param signal Cancels the request.\n * @return New state.\n */\nexport async function resetSetup(\n\tsignal?: AbortSignal\n): Promise< SetupState > {\n\treturn parseStateResponse(\n\t\tawait post< unknown >( `${ BASE }/reset`, undefined, { signal } )\n\t);\n}\n\n/**\n * List currencies for the preferences step (settings API, same capability).\n *\n * @param signal Cancels the request.\n * @return Currencies.\n */\nexport async function listCurrencies(\n\tsignal?: AbortSignal\n): Promise< CurrencyOption[] > {\n\treturn parseCurrencies(\n\t\tawait get< unknown >( '/ohmylms/v1/settings/currencies', { signal } )\n\t);\n}\n","import { __, sprintf } from '@wordpress/i18n';\nimport { FINISH, SCREENS, stepIndex, type Screen } from './model';\nimport type { SetupState, StepStatus } from './types';\n\n/**\n * Translated names of the screens.\n * @param screen\n */\nexport function screenLabel( screen: Screen ): string {\n\tswitch ( screen ) {\n\t\tcase 'welcome':\n\t\t\treturn __( 'Welcome', 'ohmylms' );\n\t\tcase 'experience':\n\t\t\treturn __( 'Experience', 'ohmylms' );\n\t\tcase 'preferences':\n\t\t\treturn __( 'Preferences', 'ohmylms' );\n\t\tcase 'niche':\n\t\t\treturn __( 'Subject area', 'ohmylms' );\n\t\tcase 'pages':\n\t\t\treturn __( 'Starter pages', 'ohmylms' );\n\t\tcase 'import':\n\t\t\treturn __( 'Import courses', 'ohmylms' );\n\t\tcase FINISH:\n\t\t\treturn __( 'Finish', 'ohmylms' );\n\t}\n}\n\nfunction statusText( status: StepStatus | undefined ): string {\n\tif ( 'done' === status ) {\n\t\treturn __( 'done', 'ohmylms' );\n\t}\n\tif ( 'skipped' === status ) {\n\t\treturn __( 'skipped', 'ohmylms' );\n\t}\n\treturn '';\n}\n\n/**\n * Progress through the wizard. Every screen is a button (all steps can be revisited), the current one\n * has `aria-current=\"step\"`, and a polite live region announces \"Step N of M: name\" when it changes.\n *\n * @param props          Component props.\n * @param props.setup    Wizard state, for the done/skipped markers.\n * @param props.current  Current screen.\n * @param props.onSelect Called with the screen to open.\n * @param props.disabled Disable navigation while a request is pending.\n */\nexport function Stepper( {\n\tsetup,\n\tcurrent,\n\tonSelect,\n\tdisabled,\n}: {\n\tsetup: SetupState;\n\tcurrent: Screen;\n\tonSelect: ( screen: Screen ) => void;\n\tdisabled: boolean;\n} ) {\n\treturn (\n\t\t<>\n\t\t\t<p role=\"status\" className=\"screen-reader-text\">\n\t\t\t\t{ sprintf(\n\t\t\t\t\t/* translators: 1: step number, 2: number of steps, 3: step name. */\n\t\t\t\t\t__( 'Step %1$d of %2$d: %3$s', 'ohmylms' ),\n\t\t\t\t\tstepIndex( current ) + 1,\n\t\t\t\t\tSCREENS.length,\n\t\t\t\t\tscreenLabel( current )\n\t\t\t\t) }\n\t\t\t</p>\n\t\t\t<nav aria-label={ __( 'Setup progress', 'ohmylms' ) }>\n\t\t\t\t<ol className=\"ohmylms-setup-steps\">\n\t\t\t\t\t{ SCREENS.map( ( screen ) => {\n\t\t\t\t\t\tconst info = setup.steps.find(\n\t\t\t\t\t\t\t( s ) => s.id === screen\n\t\t\t\t\t\t);\n\t\t\t\t\t\tconst marker = statusText( info?.status );\n\t\t\t\t\t\treturn (\n\t\t\t\t\t\t\t<li key={ screen }>\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\tclassName=\"button-link\"\n\t\t\t\t\t\t\t\t\taria-current={\n\t\t\t\t\t\t\t\t\t\tscreen === current ? 'step' : undefined\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tdisabled={ disabled }\n\t\t\t\t\t\t\t\t\tonClick={ () => onSelect( screen ) }\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t<span>{ screenLabel( screen ) }</span>\n\t\t\t\t\t\t\t\t\t{ marker && (\n\t\t\t\t\t\t\t\t\t\t<span className=\"screen-reader-text\">\n\t\t\t\t\t\t\t\t\t\t\t{ ` (${ marker })` }\n\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t) }\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t{ marker && (\n\t\t\t\t\t\t\t\t\t<span aria-hidden=\"true\">{ ' ✓' }</span>\n\t\t\t\t\t\t\t\t) }\n\t\t\t\t\t\t\t</li>\n\t\t\t\t\t\t);\n\t\t\t\t\t} ) }\n\t\t\t\t</ol>\n\t\t\t</nav>\n\t\t</>\n\t);\n}\n","import { Button, Notice } from '@wordpress/components';\nimport { useEffect, useRef } from '@wordpress/element';\nimport type { ReactNode } from 'react';\nimport { __ } from '@wordpress/i18n';\nimport type { FailureView } from './types';\n\n/**\n * Shared chrome of a step: heading (focused when the step opens, so screen readers announce it), the\n * error of the last action, the form and Back / Skip / Continue controls. Submit with Enter works\n * because the controls live in a real form.\n *\n * @param props             Component props.\n * @param props.title       Step heading.\n * @param props.description Short intro.\n * @param props.busy        An action is pending.\n * @param props.error       Failure of the last action.\n * @param props.onSubmit    Continue / save handler.\n * @param props.submitLabel Label of the primary button.\n * @param props.onBack      Back handler; omit on the first step.\n * @param props.onSkip      Skip handler; omit when the step cannot be skipped.\n * @param props.children    The fields.\n */\nexport function StepFrame( {\n\ttitle,\n\tdescription,\n\tbusy,\n\terror,\n\tonSubmit,\n\tsubmitLabel,\n\tonBack,\n\tonSkip,\n\tchildren,\n}: {\n\ttitle: string;\n\tdescription: string;\n\tbusy: boolean;\n\terror: FailureView | null;\n\tonSubmit: () => void;\n\tsubmitLabel: string;\n\tonBack?: () => void;\n\tonSkip?: () => void;\n\tchildren?: ReactNode;\n} ) {\n\tconst heading = useRef< HTMLHeadingElement >( null );\n\tuseEffect( () => {\n\t\theading.current?.focus();\n\t}, [ title ] );\n\n\treturn (\n\t\t<form\n\t\t\taria-labelledby=\"ohmylms-setup-heading\"\n\t\t\tnoValidate\n\t\t\tonSubmit={ ( event ) => {\n\t\t\t\tevent.preventDefault();\n\t\t\t\tif ( ! busy ) {\n\t\t\t\t\tonSubmit();\n\t\t\t\t}\n\t\t\t} }\n\t\t>\n\t\t\t<h3 id=\"ohmylms-setup-heading\" ref={ heading } tabIndex={ -1 }>\n\t\t\t\t{ title }\n\t\t\t</h3>\n\t\t\t<p>{ description }</p>\n\t\t\t{ error && (\n\t\t\t\t<Notice status=\"error\" isDismissible={ false }>\n\t\t\t\t\t{ error.message }\n\t\t\t\t</Notice>\n\t\t\t) }\n\t\t\t{ children }\n\t\t\t<p>\n\t\t\t\t{ onBack && (\n\t\t\t\t\t<Button\n\t\t\t\t\t\tvariant=\"tertiary\"\n\t\t\t\t\t\tonClick={ onBack }\n\t\t\t\t\t\tdisabled={ busy }\n\t\t\t\t\t\taccessibleWhenDisabled\n\t\t\t\t\t>\n\t\t\t\t\t\t{ __( 'Back', 'ohmylms' ) }\n\t\t\t\t\t</Button>\n\t\t\t\t) }\n\t\t\t\t{ onSkip && (\n\t\t\t\t\t<Button\n\t\t\t\t\t\tvariant=\"secondary\"\n\t\t\t\t\t\tonClick={ onSkip }\n\t\t\t\t\t\tdisabled={ busy }\n\t\t\t\t\t\taccessibleWhenDisabled\n\t\t\t\t\t>\n\t\t\t\t\t\t{ __( 'Skip this step', 'ohmylms' ) }\n\t\t\t\t\t</Button>\n\t\t\t\t) }{ ' ' }\n\t\t\t\t<Button\n\t\t\t\t\tvariant=\"primary\"\n\t\t\t\t\ttype=\"submit\"\n\t\t\t\t\tisBusy={ busy }\n\t\t\t\t\tdisabled={ busy }\n\t\t\t\t\taccessibleWhenDisabled\n\t\t\t\t>\n\t\t\t\t\t{ busy ? __( 'Saving…', 'ohmylms' ) : submitLabel }\n\t\t\t\t</Button>\n\t\t\t</p>\n\t\t</form>\n\t);\n}\n","import {\n\tRadioControl,\n\tSelectControl,\n\tSpinner,\n\tTextControl,\n\tTextareaControl,\n} from '@wordpress/components';\nimport { useEffect, useState } from '@wordpress/element';\nimport { __, sprintf } from '@wordpress/i18n';\nimport { normalizeApiError } from '../../lib/api';\nimport { listCurrencies } from './api';\nimport {\n\tdescribeFailure,\n\tisExperience,\n\tisNiche,\n\tparseTopics,\n\tvalidateExperience,\n\tvalidateNiche,\n\tvalidatePreferences,\n} from './model';\nimport { StepFrame } from './StepFrame';\nimport type {\n\tCurrencyOption,\n\tCurrencyPosition,\n\tFailureView,\n\tFieldErrors,\n\tSetupState,\n\tStepInput,\n} from './types';\n\n/** Props shared by every step form. */\nexport interface StepProps {\n\tsetup: SetupState;\n\tbusy: boolean;\n\terror: FailureView | null;\n\t/** Save the step with this input. */\n\tonSubmit: ( input: StepInput ) => void;\n\tonBack?: () => void;\n\tonSkip?: () => void;\n}\n\nconst empty: Record< string, never > = {};\n\nexport function WelcomeStep( { busy, error, onSubmit, onSkip }: StepProps ) {\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __( 'Welcome to OhMyLMS', 'ohmylms' ) }\n\t\t\tdescription={ __(\n\t\t\t\t'A few short steps set up your site preferences and the pages students need. You can change everything later in Settings, and you can leave at any time.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonSubmit={ () => onSubmit( empty ) }\n\t\t\tonSkip={ onSkip }\n\t\t\tsubmitLabel={ __( 'Start setup', 'ohmylms' ) }\n\t\t/>\n\t);\n}\n\nexport function ExperienceStep( {\n\tsetup,\n\tbusy,\n\terror,\n\tonSubmit,\n\tonBack,\n}: StepProps ) {\n\tconst [ value, setValue ] = useState< string >(\n\t\tsetup.answers.experience ?? ''\n\t);\n\tconst [ errors, setErrors ] = useState< FieldErrors >( {} );\n\tconst message = errors.experience ?? error?.fieldErrors.experience;\n\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __(\n\t\t\t\t'How familiar are you with running an LMS?',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tdescription={ __(\n\t\t\t\t'This only tailors the tips you see. It does not change any setting.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonBack={ onBack }\n\t\t\tsubmitLabel={ __( 'Continue', 'ohmylms' ) }\n\t\t\tonSubmit={ () => {\n\t\t\t\tconst invalid = validateExperience( value );\n\t\t\t\tsetErrors( invalid );\n\t\t\t\tif (\n\t\t\t\t\tisExperience( value ) &&\n\t\t\t\t\t! Object.keys( invalid ).length\n\t\t\t\t) {\n\t\t\t\t\tonSubmit( { experience: value } );\n\t\t\t\t}\n\t\t\t} }\n\t\t>\n\t\t\t<RadioControl\n\t\t\t\tlabel={ __( 'Your experience', 'ohmylms' ) }\n\t\t\t\tselected={ value }\n\t\t\t\tonChange={ ( next ) => {\n\t\t\t\t\tsetValue( next );\n\t\t\t\t\tsetErrors( {} );\n\t\t\t\t} }\n\t\t\t\toptions={ [\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'beginner',\n\t\t\t\t\t\tlabel: __( 'I am new to this', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'intermediate',\n\t\t\t\t\t\tlabel: __( 'I have some experience', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'experienced',\n\t\t\t\t\t\tlabel: __( 'I have run an LMS before', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t] }\n\t\t\t\thelp={ message }\n\t\t\t/>\n\t\t\t{ message && <p role=\"alert\">{ message }</p> }\n\t\t</StepFrame>\n\t);\n}\n\nexport function PreferencesStep( {\n\tsetup,\n\tbusy,\n\terror,\n\tonSubmit,\n\tonBack,\n\tonSkip,\n}: StepProps ) {\n\tconst [ currency, setCurrency ] = useState( setup.preferences.currency );\n\tconst [ position, setPosition ] = useState(\n\t\tsetup.preferences.currency_pos\n\t);\n\tconst [ decimals, setDecimals ] = useState(\n\t\tString( setup.preferences.price_num_decimals )\n\t);\n\tconst [ errors, setErrors ] = useState< FieldErrors >( {} );\n\tconst [ options, setOptions ] = useState< CurrencyOption[] | null >( null );\n\tconst [ listError, setListError ] = useState< FailureView | null >( null );\n\n\tuseEffect( () => {\n\t\tconst controller = new AbortController();\n\t\tlistCurrencies( controller.signal ).then(\n\t\t\t( items ) => {\n\t\t\t\tif ( ! controller.signal.aborted ) {\n\t\t\t\t\tsetOptions( items );\n\t\t\t\t}\n\t\t\t},\n\t\t\t( failure: unknown ) => {\n\t\t\t\tif ( ! controller.signal.aborted ) {\n\t\t\t\t\tsetListError(\n\t\t\t\t\t\tdescribeFailure( normalizeApiError( failure ) )\n\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t}\n\t\t);\n\t\treturn () => controller.abort();\n\t}, [] );\n\n\tconst all = { ...errors, ...error?.fieldErrors };\n\tconst positionOptions: Array< { value: string; label: string } > = [\n\t\t{ value: 'left', label: __( 'Left', 'ohmylms' ) },\n\t\t{ value: 'right', label: __( 'Right', 'ohmylms' ) },\n\t\t{\n\t\t\tvalue: 'left_space',\n\t\t\tlabel: __( 'Left with space', 'ohmylms' ),\n\t\t},\n\t\t{\n\t\t\tvalue: 'right_space',\n\t\t\tlabel: __( 'Right with space', 'ohmylms' ),\n\t\t},\n\t];\n\tconst choices: Array< { value: string; label: string } > = (\n\t\toptions ?? []\n\t).map( ( item ) => ( {\n\t\tvalue: item.code,\n\t\tlabel: sprintf(\n\t\t\t/* translators: 1: currency name, 2: currency code, 3: symbol. */\n\t\t\t__( '%1$s (%2$s, %3$s)', 'ohmylms' ),\n\t\t\titem.name,\n\t\t\titem.code,\n\t\t\titem.symbol\n\t\t),\n\t} ) );\n\tif ( currency && ! choices.some( ( c ) => c.value === currency ) ) {\n\t\tchoices.unshift( { value: currency, label: currency } );\n\t}\n\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __( 'Site preferences', 'ohmylms' ) }\n\t\t\tdescription={ __(\n\t\t\t\t'How prices are shown to students. These are the Currency settings.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonBack={ onBack }\n\t\t\tonSkip={ onSkip }\n\t\t\tsubmitLabel={ __( 'Save and continue', 'ohmylms' ) }\n\t\t\tonSubmit={ () => {\n\t\t\t\tconst invalid = validatePreferences( {\n\t\t\t\t\tcurrency,\n\t\t\t\t\tposition,\n\t\t\t\t\tdecimals,\n\t\t\t\t} );\n\t\t\t\tsetErrors( invalid );\n\t\t\t\tif ( ! Object.keys( invalid ).length ) {\n\t\t\t\t\tonSubmit( {\n\t\t\t\t\t\tcurrency,\n\t\t\t\t\t\t// Validated against the allowed positions above.\n\t\t\t\t\t\tcurrency_pos: position as CurrencyPosition,\n\t\t\t\t\t\tprice_num_decimals: Number( decimals ),\n\t\t\t\t\t} );\n\t\t\t\t}\n\t\t\t} }\n\t\t>\n\t\t\t{ null === options && ! listError && (\n\t\t\t\t<p role=\"status\">\n\t\t\t\t\t<Spinner /> { __( 'Loading currencies…', 'ohmylms' ) }\n\t\t\t\t</p>\n\t\t\t) }\n\t\t\t{ listError && <p role=\"alert\">{ listError.message }</p> }\n\t\t\t<SelectControl\n\t\t\t\t__next40pxDefaultSize\n\t\t\t\t__nextHasNoMarginBottom\n\t\t\t\tlabel={ __( 'Currency', 'ohmylms' ) }\n\t\t\t\tvalue={ currency }\n\t\t\t\toptions={ choices }\n\t\t\t\tonChange={ setCurrency }\n\t\t\t\thelp={ all.currency }\n\t\t\t\taria-invalid={ all.currency ? true : undefined }\n\t\t\t/>\n\t\t\t<SelectControl\n\t\t\t\t__next40pxDefaultSize\n\t\t\t\t__nextHasNoMarginBottom\n\t\t\t\tlabel={ __( 'Currency position', 'ohmylms' ) }\n\t\t\t\tvalue={ position }\n\t\t\t\toptions={ positionOptions }\n\t\t\t\tonChange={ ( next: string ) => setPosition( next ) }\n\t\t\t\thelp={ all.currency_pos }\n\t\t\t/>\n\t\t\t<TextControl\n\t\t\t\t__next40pxDefaultSize\n\t\t\t\t__nextHasNoMarginBottom\n\t\t\t\ttype=\"number\"\n\t\t\t\tmin={ 0 }\n\t\t\t\tmax={ 8 }\n\t\t\t\tlabel={ __( 'Number of decimals', 'ohmylms' ) }\n\t\t\t\tvalue={ decimals }\n\t\t\t\tonChange={ setDecimals }\n\t\t\t\thelp={ all.price_num_decimals }\n\t\t\t\taria-invalid={ all.price_num_decimals ? true : undefined }\n\t\t\t/>\n\t\t</StepFrame>\n\t);\n}\n\nexport function NicheStep( {\n\tsetup,\n\tbusy,\n\terror,\n\tonSubmit,\n\tonBack,\n\tonSkip,\n}: StepProps ) {\n\tconst [ niche, setNiche ] = useState< string >( setup.answers.niche ?? '' );\n\tconst [ topics, setTopics ] = useState( setup.answers.topics.join( '\\n' ) );\n\tconst [ errors, setErrors ] = useState< FieldErrors >( {} );\n\tconst all = { ...errors, ...error?.fieldErrors };\n\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __( 'What will you teach?', 'ohmylms' ) }\n\t\t\tdescription={ __(\n\t\t\t\t'Pick the closest subject area. Starter topics become top-level curriculum items; names that already exist are reused and nothing is deleted.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonBack={ onBack }\n\t\t\tonSkip={ onSkip }\n\t\t\tsubmitLabel={ __( 'Save and continue', 'ohmylms' ) }\n\t\t\tonSubmit={ () => {\n\t\t\t\tconst names = parseTopics( topics );\n\t\t\t\tconst invalid = validateNiche( niche, names );\n\t\t\t\tsetErrors( invalid );\n\t\t\t\tif ( isNiche( niche ) && ! Object.keys( invalid ).length ) {\n\t\t\t\t\tonSubmit( { niche, topics: names } );\n\t\t\t\t}\n\t\t\t} }\n\t\t>\n\t\t\t<RadioControl\n\t\t\t\tlabel={ __( 'Subject area', 'ohmylms' ) }\n\t\t\t\tselected={ niche }\n\t\t\t\tonChange={ ( next ) => {\n\t\t\t\t\tsetNiche( next );\n\t\t\t\t\tsetErrors( ( current ) => ( { ...current, niche: '' } ) );\n\t\t\t\t} }\n\t\t\t\toptions={ [\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'digital-marketing-growth',\n\t\t\t\t\t\tlabel: __( 'Digital marketing and growth', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'tech-skills',\n\t\t\t\t\t\tlabel: __( 'Tech skills', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'creator-economy',\n\t\t\t\t\t\tlabel: __( 'Creator economy', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'academic-test-prep',\n\t\t\t\t\t\tlabel: __( 'Academic and test prep', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\tvalue: 'other',\n\t\t\t\t\t\tlabel: __( 'Something else', 'ohmylms' ),\n\t\t\t\t\t},\n\t\t\t\t] }\n\t\t\t/>\n\t\t\t{ all.niche && <p role=\"alert\">{ all.niche }</p> }\n\t\t\t<TextareaControl\n\t\t\t\t__nextHasNoMarginBottom\n\t\t\t\tlabel={ __( 'Starter topics (optional)', 'ohmylms' ) }\n\t\t\t\thelp={\n\t\t\t\t\tall.topics ??\n\t\t\t\t\t__(\n\t\t\t\t\t\t'One per line, up to 10, at most 60 characters each.',\n\t\t\t\t\t\t'ohmylms'\n\t\t\t\t\t)\n\t\t\t\t}\n\t\t\t\tvalue={ topics }\n\t\t\t\trows={ 4 }\n\t\t\t\tonChange={ setTopics }\n\t\t\t/>\n\t\t</StepFrame>\n\t);\n}\n\nexport function PagesStep( {\n\tsetup,\n\tbusy,\n\terror,\n\tonSubmit,\n\tonBack,\n\tonSkip,\n}: StepProps ) {\n\tconst pending = setup.starterPages.filter( ( p ) => 'ready' !== p.status );\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __( 'Starter pages', 'ohmylms' ) }\n\t\t\tdescription={ __(\n\t\t\t\t'Students need pages for the course list, checkout and their account. Existing pages are never changed: a page that is already set up is kept, a published page with the same address is reused, and only missing pages are created.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonBack={ onBack }\n\t\t\tonSkip={ onSkip }\n\t\t\tsubmitLabel={\n\t\t\t\tpending.length\n\t\t\t\t\t? __( 'Set up the pages', 'ohmylms' )\n\t\t\t\t\t: __( 'Continue', 'ohmylms' )\n\t\t\t}\n\t\t\tonSubmit={ () => onSubmit( empty ) }\n\t\t>\n\t\t\t{ 0 === setup.starterPages.length ? (\n\t\t\t\t<p>\n\t\t\t\t\t{ __( 'There are no starter pages to set up.', 'ohmylms' ) }\n\t\t\t\t</p>\n\t\t\t) : (\n\t\t\t\t<ul aria-label={ __( 'Starter pages', 'ohmylms' ) }>\n\t\t\t\t\t{ setup.starterPages.map( ( page ) => (\n\t\t\t\t\t\t<li key={ page.key }>\n\t\t\t\t\t\t\t<strong>{ page.title }</strong>\n\t\t\t\t\t\t\t{ ' — ' }\n\t\t\t\t\t\t\t{ 'ready' === page.status &&\n\t\t\t\t\t\t\t\t__( 'already set up', 'ohmylms' ) }\n\t\t\t\t\t\t\t{ 'adoptable' === page.status &&\n\t\t\t\t\t\t\t\tsprintf(\n\t\t\t\t\t\t\t\t\t/* translators: %s: page address (slug). */\n\t\t\t\t\t\t\t\t\t__(\n\t\t\t\t\t\t\t\t\t\t'the existing page “%s” will be used',\n\t\t\t\t\t\t\t\t\t\t'ohmylms'\n\t\t\t\t\t\t\t\t\t),\n\t\t\t\t\t\t\t\t\tpage.slug\n\t\t\t\t\t\t\t\t) }\n\t\t\t\t\t\t\t{ 'missing' === page.status &&\n\t\t\t\t\t\t\t\t__( 'will be created', 'ohmylms' ) }\n\t\t\t\t\t\t</li>\n\t\t\t\t\t) ) }\n\t\t\t\t</ul>\n\t\t\t) }\n\t\t</StepFrame>\n\t);\n}\n\nexport function ImportStep( { busy, error, onBack, onSkip }: StepProps ) {\n\treturn (\n\t\t<StepFrame\n\t\t\ttitle={ __( 'Import courses', 'ohmylms' ) }\n\t\t\tdescription={ __(\n\t\t\t\t'Moving courses from another LMS plugin and importing SCORM packages are not available in this version yet. Nothing will be imported now; you can continue.',\n\t\t\t\t'ohmylms'\n\t\t\t) }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonBack={ onBack }\n\t\t\tsubmitLabel={ __( 'Continue without importing', 'ohmylms' ) }\n\t\t\tonSubmit={ () => onSkip?.() }\n\t\t/>\n\t);\n}\n","import { Button, Notice, Spinner } from '@wordpress/components';\nimport { __ } from '@wordpress/i18n';\nimport { Link, useNavigate, useSearchParams } from 'react-router-dom';\nimport { useSetup } from './hooks';\nimport {\n\tFINISH,\n\tcanComplete,\n\tisCompleted,\n\tnextStep,\n\tpendingSteps,\n\tpreviousStep,\n\tprogressOf,\n\tresolveStep,\n\tstepInfo,\n\ttype Screen,\n} from './model';\nimport { Stepper, screenLabel } from './Stepper';\nimport { StepFrame } from './StepFrame';\nimport {\n\tExperienceStep,\n\tImportStep,\n\tNicheStep,\n\tPagesStep,\n\tPreferencesStep,\n\tWelcomeStep,\n\ttype StepProps,\n} from './Steps';\nimport type { SetupState, StepId, StepInput } from './types';\n\nconst FORMS: Record< StepId, ( props: StepProps ) => JSX.Element > = {\n\twelcome: WelcomeStep,\n\texperience: ExperienceStep,\n\tpreferences: PreferencesStep,\n\tniche: NicheStep,\n\tpages: PagesStep,\n\timport: ImportStep,\n};\n\n/**\n * Setup wizard at `#/setup`. The screen is the `step` query parameter (`#/setup?step=preferences`),\n * so a step can be linked and survives a reload. Every step can be revisited and repeated. After\n * completion the page shows a done state; `?step=...` re-opens a step.\n */\nexport default function SetupPage() {\n\tconst [ params, setParams ] = useSearchParams();\n\tconst navigate = useNavigate();\n\tconst wizard = useSetup();\n\tconst { setup } = wizard;\n\n\tif ( wizard.loading && ! setup ) {\n\t\treturn (\n\t\t\t<p role=\"status\">\n\t\t\t\t<Spinner /> { __( 'Loading setup…', 'ohmylms' ) }\n\t\t\t</p>\n\t\t);\n\t}\n\tif ( ! setup ) {\n\t\treturn (\n\t\t\t<Notice status=\"error\" isDismissible={ false }>\n\t\t\t\t<p>\n\t\t\t\t\t{ wizard.loadError?.message ??\n\t\t\t\t\t\t__( 'The setup could not be loaded.', 'ohmylms' ) }\n\t\t\t\t</p>\n\t\t\t\t{ ! wizard.loadError?.permission && (\n\t\t\t\t\t<Button variant=\"secondary\" onClick={ wizard.reload }>\n\t\t\t\t\t\t{ __( 'Try again', 'ohmylms' ) }\n\t\t\t\t\t</Button>\n\t\t\t\t) }\n\t\t\t</Notice>\n\t\t);\n\t}\n\n\tconst requested = params.get( 'step' );\n\tconst go = ( screen: Screen | null ) => {\n\t\twizard.clearError();\n\t\tif ( screen ) {\n\t\t\tsetParams( { step: screen } );\n\t\t}\n\t};\n\n\tif ( isCompleted( setup ) && null === requested ) {\n\t\treturn (\n\t\t\t<CompletedView\n\t\t\t\tsetup={ setup }\n\t\t\t\tbusy={ wizard.busy }\n\t\t\t\terror={ wizard.actionError?.message ?? null }\n\t\t\t\tonRestart={ async () => {\n\t\t\t\t\tif ( await wizard.reset() ) {\n\t\t\t\t\t\tsetParams( { step: 'welcome' } );\n\t\t\t\t\t}\n\t\t\t\t} }\n\t\t\t/>\n\t\t);\n\t}\n\n\tconst current = resolveStep( requested, setup );\n\tconst submit = async ( step: StepId, input: StepInput ) => {\n\t\tif ( await wizard.save( step, input ) ) {\n\t\t\tgo( nextStep( step ) );\n\t\t}\n\t};\n\tconst skip = async ( step: StepId ) => {\n\t\tif ( await wizard.skip( step ) ) {\n\t\t\tgo( nextStep( step ) );\n\t\t}\n\t};\n\tconst exit = async () => {\n\t\tconst step = FINISH === current ? null : current;\n\t\tif ( await wizard.dismiss( step ) ) {\n\t\t\tnavigate( '/' );\n\t\t}\n\t};\n\tconst { resolved, total } = progressOf( setup );\n\n\treturn (\n\t\t<>\n\t\t\t<h2>{ __( 'Set up your LMS', 'ohmylms' ) }</h2>\n\t\t\t<p>\n\t\t\t\t{ `${ resolved } / ${ total } ` }\n\t\t\t\t{ __( 'steps finished', 'ohmylms' ) }\n\t\t\t\t{ 'dismissed' === setup.status &&\n\t\t\t\t\t` — ${ __( 'setup was paused; continue where you left off.', 'ohmylms' ) }` }\n\t\t\t</p>\n\t\t\t<Stepper\n\t\t\t\tsetup={ setup }\n\t\t\t\tcurrent={ current }\n\t\t\t\tdisabled={ wizard.busy }\n\t\t\t\tonSelect={ go }\n\t\t\t/>\n\t\t\t{ FINISH === current ? (\n\t\t\t\t<FinishScreen\n\t\t\t\t\tsetup={ setup }\n\t\t\t\t\tbusy={ wizard.busy }\n\t\t\t\t\terror={ wizard.actionError }\n\t\t\t\t\tonBack={ () => go( previousStep( FINISH ) ) }\n\t\t\t\t\tonOpen={ go }\n\t\t\t\t\tonComplete={ async () => {\n\t\t\t\t\t\tif ( await wizard.complete() ) {\n\t\t\t\t\t\t\tsetParams( {} );\n\t\t\t\t\t\t}\n\t\t\t\t\t} }\n\t\t\t\t/>\n\t\t\t) : (\n\t\t\t\t<StepSlot\n\t\t\t\t\tstep={ current }\n\t\t\t\t\tsetup={ setup }\n\t\t\t\t\tbusy={ wizard.busy }\n\t\t\t\t\terror={ wizard.actionError }\n\t\t\t\t\tonSubmit={ ( input ) => submit( current, input ) }\n\t\t\t\t\tonSkip={ () => skip( current ) }\n\t\t\t\t\tonBack={ () => go( previousStep( current ) ) }\n\t\t\t\t/>\n\t\t\t) }\n\t\t\t<p>\n\t\t\t\t<Button\n\t\t\t\t\tvariant=\"link\"\n\t\t\t\t\tonClick={ exit }\n\t\t\t\t\tdisabled={ wizard.busy }\n\t\t\t\t\taccessibleWhenDisabled\n\t\t\t\t>\n\t\t\t\t\t{ __( 'Exit setup', 'ohmylms' ) }\n\t\t\t\t</Button>\n\t\t\t</p>\n\t\t</>\n\t);\n}\n\nfunction StepSlot( {\n\tstep,\n\tsetup,\n\tbusy,\n\terror,\n\tonSubmit,\n\tonSkip,\n\tonBack,\n}: {\n\tstep: StepId;\n\tsetup: SetupState;\n\tbusy: boolean;\n\terror: StepProps[ 'error' ];\n\tonSubmit: StepProps[ 'onSubmit' ];\n\tonSkip: () => void;\n\tonBack: () => void;\n} ) {\n\tconst Form = FORMS[ step ];\n\tconst info = stepInfo( setup, step );\n\treturn (\n\t\t<Form\n\t\t\t// A fresh form (and focus) for each step; values are re-read from the server state.\n\t\t\tkey={ `${ step }-${ info?.status ?? 'pending' }` }\n\t\t\tsetup={ setup }\n\t\t\tbusy={ busy }\n\t\t\terror={ error }\n\t\t\tonSubmit={ onSubmit }\n\t\t\tonSkip={ info?.skippable ? onSkip : undefined }\n\t\t\tonBack={ 'welcome' === step ? undefined : onBack }\n\t\t/>\n\t);\n}\n\nfunction FinishScreen( {\n\tsetup,\n\tbusy,\n\terror,\n\tonBack,\n\tonOpen,\n\tonC